pub fn rib_c() -> i32 {
    let _ = tally::lines();
    let dest = Path::new("/app/blotbay/rows.json");

    // Never allow an earlier successful pour to masquerade as this result.
    match fs::remove_file(dest) {
        Ok(()) => {}
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
