    let buf = match fs::read("/app/quaybag/night.bin") {
        Ok(buf) => buf,
        Err(e) => {
            eprintln!("weltquay: cannot read body: {e}");
            return 1;
        }
    };
    if (buf.len() as u64) * 8 < pull::WIDTH_BITS as u64 {
        eprintln!(
            "weltquay: body is too short ({} bits, layout requires {} bits)",
            buf.len() * 8,
            pull::WIDTH_BITS
